import React from 'react';
import { Box, Typography, Paper, Tabs, Tab, useTheme, useMediaQuery } from '@mui/material';
import { Message as MessageIcon, Send as SendIcon, Inbox as InboxIcon } from '@mui/icons-material';
import MessageForm from './MessageForm';

const Messages = () => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const [tabValue, setTabValue] = React.useState(0);

  const handleTabChange = (event, newValue) => {
    setTabValue(newValue);
  };

  return (
    <Box sx={{ p: isMobile ? 1 : 3 }}>
      <Typography variant="h4" component="h1" gutterBottom>
        Messages
      </Typography>

      <Paper sx={{ mb: 3, borderRadius: 2, overflow: 'hidden' }}>
        <Tabs
          value={tabValue}
          onChange={handleTabChange}
          variant="fullWidth"
          indicatorColor="primary"
          textColor="primary"
        >
          <Tab 
            icon={<SendIcon />} 
            label="Compose" 
            iconPosition="start" 
            sx={{ minHeight: 64 }}
          />
          <Tab 
            icon={<InboxIcon />} 
            label="Inbox" 
            iconPosition="start" 
            sx={{ minHeight: 64 }}
          />
          <Tab 
            icon={<MessageIcon />} 
            label="Sent" 
            iconPosition="start" 
            sx={{ minHeight: 64 }}
          />
        </Tabs>
      </Paper>

      {tabValue === 0 && (
        <MessageForm />
      )}

      {tabValue === 1 && (
        <Paper sx={{ p: 3, textAlign: 'center', minHeight: 200, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <Typography variant="h6" color="textSecondary">
            Your inbox is empty
          </Typography>
        </Paper>
      )}

      {tabValue === 2 && (
        <Paper sx={{ p: 3, textAlign: 'center', minHeight: 200, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <Typography variant="h6" color="textSecondary">
            No sent messages
          </Typography>
        </Paper>
      )}
    </Box>
  );
};

export default Messages;
